#plans{padding-bottom:44px;}
#athletes-say{padding-top:32px;}
.art-photo img{object-position:50% 32%;}
.tips-photo img{object-position:50% 28%;}
.guidance--calm .art-photo.taper-rocks-photo img{object-position:50% 38%;}
.guidance--calm .art-photo.taper-venue-photo img{object-position:50% 68%;}
@media(max-width:600px){.hero--bleed .wrap{align-items:end;padding-bottom:26px;}#plans{padding-bottom:36px;}#athletes-say{padding-top:28px;}.guidance--calm .art-photo.taper-rocks-photo img{object-position:50% 40%;}.guidance--calm .art-photo.taper-venue-photo img{object-position:50% 70%;}}
